    <!-- ══════════════════════ INITIAL LOADING ══ -->
    <v-container v-else class="mt-8 text-center">
      <v-progress-circular indeterminate color="primary" size="64" />
      <div class="mt-4 grey--text text-body-1">Verifying access…</div>
    </v-container>

    <!-- ══════════════════════════ DETAIL VIEW ══ -->
    <view-training-need
      v-model="detailDialog"
      :need="detailNeed"
      @edit="editNeed"
