<script>
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";
import { eventBus } from "@/main";

const EXT = {
  NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
  DEPARTMENT: "http://ihris.org/fhir/StructureDefinition/department",
  CADRE: "http://ihris.org/fhir/StructureDefinition/cadre",
  DESCRIPTION: "http://ihris.org/fhir/StructureDefinition/description",
  START_DATE: "http://ihris.org/fhir/StructureDefinition/start-date",
  END_DATE: "http://ihris.org/fhir/StructureDefinition/end-date",
  FISCAL_YEAR: "http://ihris.org/fhir/StructureDefinition/fiscal-year",
  FACILITY: "http://ihris.org/fhir/StructureDefinition/facility",
};

const TRAINING_NEED_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/training-need-profile";

export default {
  name: "TrainingNeed",

  mixins: [generalMixin, processQuestionnaire],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/ihris-training-need",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/training-need-profile",
      accessChecked: false,
      isHR: false,
      allowedFacilities: [],
      currentFiscalYear: null,
      formKey: 0,
      isEdit: true,
      valid: false,
      trainingNeeds: [],
      loadingNeeds: false,
      facilityDialog: false,
      facilitySearch: "",

      facilityPickerHeaders: [
        { text: "", value: "_check", sortable: false, width: "48px" },
        { text: "Facility", value: "name", sortable: true },
        { text: "ID", value: "id", sortable: false },
      ],
      cadreRows: [{}],
      form: {
        name: "",
        department: "",
        cadres: [],
        description: "",
        startDate: "",
        endDate: "",
        facilities: [],
      },
      saving: false,
      loading: false,
      facilitiesError: false,
      detailDialog: false,
      detailNeed: null,
      snackbar: { show: false, text: "", color: "success" },

      tableHeaders: [
        { text: "Title", value: "name", sortable: true },
        { text: "Department", value: "deptDisplay", sortable: true },
        { text: "Cadres", value: "cadres", sortable: false },
        { text: "Period", value: "period", sortable: false },
        { text: "Facilities", value: "facilityNames", sortable: false },
        { text: "", value: "actions", sortable: false, align: "end" },
      ],
    };
  },

  computed: {
    filteredAllowedFacilities() {
      if (!this.facilitySearch) return this.allowedFacilities;
      const q = this.facilitySearch.toLowerCase();
      return this.allowedFacilities.filter(function(f) {
        return (
          f.name.toLowerCase().indexOf(q) !== -1 ||
          f.id.toLowerCase().indexOf(q) !== -1
        );
      });
    },

    allFilteredSelected() {
      const filtered = this.filteredAllowedFacilities;
      if (!filtered.length) return false;
      return filtered.every((f) => this.isFacilitySelected(f));
    },

    someFilteredSelected() {
      const filtered = this.filteredAllowedFacilities;
      if (!filtered.length) return false;
      return (
        filtered.some((f) => this.isFacilitySelected(f)) &&
        !this.allFilteredSelected
      );
    },

    facilityPickerLabel() {
      const n = this.form.facilities.length;
      if (!n) return "";
      return n + " " + (n === 1 ? "facility" : "facilities") + " selected";
    },
  },

  created() {
    eventBus.$on("Basic.name", (value) => {
      this.form.name = value || "";
    });

    eventBus.$on("Basic.department", (value) => {
      if (!value) {
        this.form.department = "";
        return;
      }
      this.form.department = value.split("#")[1] || "";
    });

    eventBus.$on("Basic.description", (value) => {
      this.form.description = value || "";
    });

    eventBus.$on("Basic.startDate", (value) => {
      this.form.startDate = value || "";
    });

    eventBus.$on("Basic.endDate", (value) => {
      this.form.endDate = value || "";
    });
  },

  async mounted() {
    this.loading = true;

    await this.$nextTick();

    // Wait for generalMixin.getUserDepartment() to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    await this.checkAccess();
    if (this.isHR) {
      await this.loadFiscalYear();
      await this.loadTrainingNeeds();
    }
    this.loading = false;
  },

  methods: {
    async checkAccess() {
      try {
        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch("/site/general/getHR/" + practitionerId);
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const hrList = await resp.json();

        const matched = Array.isArray(hrList)
          ? hrList.find((h) =>
              h.practitioners.find((p) => p === practitionerId),
            )
          : null;

        if (!matched) {
          this.isHR = false;
          this.accessChecked = true;
          return;
        }

        this.isHR = true;

        // coverage is always a flat array of { id, name } facility objects
        const coverageArr = Array.isArray(matched.coverage)
          ? matched.coverage
          : [];
        this.allowedFacilities = coverageArr.map(function(f) {
          return { id: f.id, name: f.name };
        });
      } catch (err) {
        console.error("checkAccess error:", err);
        this.showSnackbar("Failed to verify HR access.", "error");
        this.isHR = false;
      } finally {
        this.accessChecked = true;
      }
    },

    // ════════════════════════════════════════ FISCAL YEAR ══

    async loadFiscalYear() {
      try {
        const resp = await fetch("/site/leave/getFinancialYear");
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const data = await resp.json();
        this.currentFiscalYear = data.year;
      } catch (err) {
        console.error("loadFiscalYear error:", err);
      }
    },

    // ════════════════════════════════ TRAINING NEEDS LIST ══

    async loadTrainingNeeds() {
      if (!this.currentFiscalYear) return;
      this.loadingNeeds = true;
      try {
        const coveredIds = new Set(
          this.allowedFacilities.map(function(f) {
            return f.id;
          }),
        );
        const params = new URLSearchParams({
          _profile: TRAINING_NEED_PROFILE,
          facility: Array.from(coveredIds).join(","),
          enddate: `ge${this.$moment().format("YYYY-MM-DD")}`,
          _count: "500",
        });
        let resp = await fetch("/fhir/Basic?" + params);
        resp = await resp.json();

        this.trainingNeeds = (resp && resp.entry ? resp.entry : []).map((e) =>
          this.parseTrainingNeed(e.resource),
        );
      } catch (err) {
        console.error("loadTrainingNeeds error:", err);
        this.showSnackbar("Failed to load training needs.", "error");
      } finally {
        this.loadingNeeds = false;
      }
    },

    parseTrainingNeed(resource) {
      const ext = (url) =>
        resource.extension &&
        resource.extension.find(function(e) {
          return e.url === url;
        });
      const extAll = (url) =>
        (resource.extension &&
          resource.extension.filter(function(e) {
            return e.url === url;
          })) ||
        [];

      const dept = ext(EXT.DEPARTMENT) && ext(EXT.DEPARTMENT).valueCoding;
      const facRefs = extAll(EXT.FACILITY)
        .map(function(e) {
          return e.valueReference && e.valueReference.reference;
        })
        .filter(Boolean);
      const facIds = facRefs.map(function(r) {
        return r.split("/").pop();
      });

      const facMap = {};
      this.allowedFacilities.forEach(function(f) {
        facMap[f.id] = f.name;
      });
      const facilityNames = facIds
        .map(function(id) {
          return facMap[id] || id;
        })
        .join(", ");

      return {
        id: resource.id,
        name: ext(EXT.NAME) ? ext(EXT.NAME).valueString : "—",
        description: ext(EXT.DESCRIPTION)
          ? ext(EXT.DESCRIPTION).valueString
          : "—",
        deptDisplay: dept ? dept.display || dept.code : "—",
        cadres: extAll(EXT.CADRE)
          .map(function(e) {
            return e.valueCoding;
          })
          .filter(Boolean),
        startDate: ext(EXT.START_DATE) ? ext(EXT.START_DATE).valueDate : "",
        endDate: ext(EXT.END_DATE) ? ext(EXT.END_DATE).valueDate : "",
        facilityIds: facIds,
        facilityNames: facilityNames || "—",
        _resource: resource,
      };
    },

    // ═══════════════════════════════════ FACILITY PICKER ══

    toggleSelectAll() {
      if (this.allFilteredSelected) {
        // Deselect every facility currently visible in the filtered list
        const filteredIds = new Set(
          this.filteredAllowedFacilities.map((f) => f.id),
        );
        this.form.facilities = this.form.facilities.filter(
          (f) => !filteredIds.has(f.id),
        );
      } else {
        // Add every filtered facility that isn't already selected
        const existingIds = new Set(this.form.facilities.map((f) => f.id));
        this.filteredAllowedFacilities.forEach((f) => {
          if (!existingIds.has(f.id)) {
            this.form.facilities = this.form.facilities.concat([
              { id: f.id, name: f.name },
            ]);
          }
        });
      }
    },

    isFacilitySelected(facility) {
      return this.form.facilities.some(function(f) {
        return f.id === facility.id;
      });
    },

    facilityRowClass(item) {
      return this.isFacilitySelected(item) ? "tn-row-selected" : "";
    },

    toggleFacility(facility) {
      if (this.isFacilitySelected(facility)) {
        this.form.facilities = this.form.facilities.filter(function(f) {
          return f.id !== facility.id;
        });
      } else {
        this.form.facilities = this.form.facilities.concat([
          { id: facility.id, name: facility.name },
        ]);
      }
    },

    removeFacility(facility) {
      this.form.facilities = this.form.facilities.filter(function(f) {
        return f.id !== facility.id;
      });
    },

    // ════════════════════════════════════════════ FORM ══

    viewNeed(item) {
      this.detailNeed = item;
      this.detailDialog = true;
    },

    editNeed(item) {
      this.fhirId = item.id;
      this.facilitiesError = false;

      const r = item._resource;
      const ext = (url) =>
        r.extension &&
        r.extension.find(function(e) {
          return e.url === url;
        });
      const extAll = (url) =>
        (r.extension &&
          r.extension.filter(function(e) {
            return e.url === url;
          })) ||
        [];

      const dept = ext(EXT.DEPARTMENT) && ext(EXT.DEPARTMENT).valueCoding;
      const facRefs = extAll(EXT.FACILITY)
        .map(function(e) {
          return e.valueReference && e.valueReference.reference;
        })
        .filter(Boolean);

      const facMap = {};
      this.allowedFacilities.forEach(function(f) {
        facMap[f.id] = f;
      });
      const facilities = facRefs.map(function(ref) {
        const id = ref.split("/").pop();
        return facMap[id] || { id: id, name: id };
      });

      var cadreCodings = extAll(EXT.CADRE)
        .map(function(e) {
          return e.valueCoding || null;
        })
        .filter(Boolean);

      this.cadreRows = cadreCodings.length
        ? cadreCodings.map(function() {
            return {};
          })
        : [{}];
      this.form = {
        name: ext(EXT.NAME) ? ext(EXT.NAME).valueString : "",
        department: dept ? dept.code : "",
        cadres: cadreCodings.map(function(c) {
          return c.code || "";
        }),
        description: ext(EXT.DESCRIPTION)
          ? ext(EXT.DESCRIPTION).valueString
          : "",
        startDate: ext(EXT.START_DATE) ? ext(EXT.START_DATE).valueDate : "",
        endDate: ext(EXT.END_DATE) ? ext(EXT.END_DATE).valueDate : "",
        facilities: facilities,
      };
      this.facilitiesError = false;
      this.formKey++;
      this.valid = true;
      this.$nextTick(function() {
        if (this.$refs.form) this.$refs.form.validate();
        const el = document.querySelector(".tn-form-card");
        if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    },

    resetForm() {
      if (this.$refs.form) {
        this.$refs.form.resetValidation();
      }
      this.fhirId = "";
      this.facilitiesError = false;
      this.cadreRows = [{}];
      this.form = {
        name: "",
        department: "",
        cadres: [],
        description: "",
        startDate: "",
        endDate: "",
        facilities: [],
      };
      this.formKey++;
    },

    async submitForm() {
      if (!this.form.facilities.length) {
        this.facilitiesError = true;
        return;
      }
      this.facilitiesError = false;
      this.$refs.form.validate();
      if (!this.valid) return;

      this.saving = true;
      try {
        this.fhir = {
          facilities: this.form.facilities,
        };
        await this.processFHIR();

        this.showSnackbar(
          this.fhirId
            ? "Training need updated successfully."
            : "Training need saved successfully.",
          "success",
        );
        this.resetForm();
        await this.loadTrainingNeeds();
      } catch (err) {
        console.error("submitForm error:", err);
        this.showSnackbar(
          "Failed to save training need. Please try again.",
          "error",
        );
      } finally {
        this.saving = false;
      }
    },

    // ═══════════════════════════ CADRE ROW MANAGEMENT ══

    addCadreRow() {
      this.cadreRows.push({});
      this.form.cadres.push(null);
    },

    removeCadreRow(index) {
      if (this.cadreRows.length > 1) {
        this.cadreRows.splice(index, 1);
        this.form.cadres.splice(index, 1);
      }
    },

    // ══════════════════════════════════════ HELPERS ══

    showSnackbar(text, color) {
      this.snackbar = { show: true, text: text, color: color || "success" };
    },
  },

  components: {
    "view-training-need": () => import("./view-training-need"),
    "fhir-string": () => import("@/components/fhir/fhir-string"),
    "fhir-choice": () => import("@/components/fhir/fhir-choice"),
    "fhir-date": () => import("@/components/fhir/fhir-date"),
    "ihris-questionnaire-section": () =>
      import("@/components/ihris/ihris-questionnaire-section"),
  },
};
</script>

